            if coeff < 0:
                sign = '-'
            else:
                sign = ''
        else:
            if coeff < 0:
                sign = '-'
            else:
                sign = '+'

        abs_coeff = abs(coeff)

        # Determine the coefficient part
        if degree == 0:
            # Constant term
            coeff_part = str(abs_coeff)
        else:
            # Variable term
            if abs_coeff == 1:
                coeff_part = ''
            else:
                coeff_part = str(abs_coeff)

        # Determine the variable part
        if degree == 0:
            var_part = ''
        elif degree == 1:
